-- NAIKIN / instalasi baru pada project Supabase kosong.
create extension if not exists pgcrypto;
create table public.naikin_profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',role text not null default 'user' check(role in ('user','admin')),preferences jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.naikin_products(id text primary key,category text not null,name text not null,description text not null default '',qty_type text not null check(qty_type in ('fixed','unit')),unit_label text,duration text,min_qty integer not null default 1,max_qty integer not null default 1,step_qty integer not null default 1,price numeric(14,2) not null default 0,price_per_unit numeric(14,4) not null default 0,active boolean not null default true,sort_order integer not null default 0,updated_at timestamptz not null default now(),check(min_qty>=1 and max_qty>=min_qty and step_qty>=1),check(price>=0 and price_per_unit>=0));
create table public.naikin_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),product_id text not null references public.naikin_products(id),quantity integer not null,target text not null,total numeric(14,2) not null,status text not null default 'pending' check(status in ('pending','processing','completed','cancelled')),request_key uuid not null,created_at timestamptz not null default now(),unique(user_id,request_key));
create table public.naikin_deposits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount numeric(14,2) not null check(amount>=10000),status text not null default 'pending' check(status in ('pending','user_confirmed','paid','rejected')),request_key uuid not null,created_at timestamptz not null default now(),verified_at timestamptz,unique(user_id,request_key));
create table public.naikin_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount numeric(14,2) not null,reference text not null unique,description text not null default '',created_at timestamptz not null default now());
create table public.naikin_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),category text not null,subject text not null,message text not null,status text not null default 'open' check(status in ('open','in_progress','closed')),created_at timestamptz not null default now());
create table public.naikin_ticket_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.naikin_tickets(id) on delete cascade,sender_id uuid not null references auth.users(id),body text not null,created_at timestamptz not null default now());
create table public.naikin_site_settings(key text primary key,value jsonb not null,updated_at timestamptz not null default now());
create table public.naikin_audit(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,target text,created_at timestamptz not null default now());
insert into public.naikin_site_settings(key,value) values('qris_url','{"url":""}'),('announcement','{"text":""}'),('homepage','{"headline":"Yang kamu cari, ada di sini."}');
create or replace function public.naikin_is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.naikin_profiles where id=(select auth.uid()) and role='admin')$$;
revoke all on function public.naikin_is_admin() from public;grant execute on function public.naikin_is_admin() to authenticated;
create or replace function public.naikin_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.naikin_profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''));insert into public.naikin_ledger(user_id,amount,reference,description) values(new.id,9500,'signup:'||new.id,'Bonus pendaftaran');return new;end$$;
create trigger naikin_on_auth_user after insert on auth.users for each row execute function public.naikin_new_user();
create or replace function public.naikin_balance() returns numeric language sql stable security definer set search_path='' as $$select coalesce(sum(amount),0) from public.naikin_ledger where user_id=(select auth.uid())$$;
revoke all on function public.naikin_balance() from public;grant execute on function public.naikin_balance() to authenticated;
create or replace function public.naikin_place_order(p_product_id text,p_quantity integer,p_target text,p_request_key uuid) returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();p public.naikin_products%rowtype;v_total numeric;v_id uuid;begin if u is null then raise exception 'Silakan masuk';end if;select id into v_id from public.naikin_orders where user_id=u and request_key=p_request_key;if found then return v_id;end if;perform pg_advisory_xact_lock(hashtext(u::text));select * into p from public.naikin_products where id=p_product_id and active=true;if not found then raise exception 'Produk tidak tersedia';end if;if p_quantity<1 or (p.qty_type='fixed' and p_quantity<>1) or (p.qty_type='unit' and (p_quantity<p.min_qty or p_quantity>p.max_qty or mod(p_quantity-p.min_qty,p.step_qty)<>0)) then raise exception 'Jumlah tidak valid';end if;if length(trim(p_target))<2 or length(p_target)>500 then raise exception 'Tujuan pesanan tidak valid';end if;if not exists(select 1 from public.naikin_deposits where user_id=u and status='paid' and amount>=15000) then raise exception 'Deposit pertama minimal Rp15.000 harus terverifikasi sebelum memesan';end if;v_total:=case when p.qty_type='fixed' then p.price else round(p.price_per_unit*p_quantity,0) end;if v_total<=0 then raise exception 'Harga tidak valid';end if;if (select coalesce(sum(amount),0) from public.naikin_ledger where user_id=u)<v_total then raise exception 'Saldo tidak mencukupi';end if;insert into public.naikin_orders(user_id,product_id,quantity,target,total,request_key) values(u,p.id,p_quantity,trim(p_target),v_total,p_request_key) returning id into v_id;insert into public.naikin_ledger(user_id,amount,reference,description) values(u,-v_total,'order:'||v_id,'Pembelian '||p.name);return v_id;end$$;
create or replace function public.naikin_create_deposit(p_amount numeric,p_request_key uuid) returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();v_id uuid;begin if u is null then raise exception 'Silakan masuk';end if;if p_amount<10000 or p_amount>100000000 or p_amount<>trunc(p_amount) then raise exception 'Nominal deposit tidak valid';end if;insert into public.naikin_deposits(user_id,amount,request_key) values(u,p_amount,p_request_key) on conflict(user_id,request_key) do update set request_key=excluded.request_key returning id into v_id;return v_id;end$$;
create or replace function public.naikin_confirm_deposit(p_deposit_id uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.naikin_deposits set status='user_confirmed' where id=p_deposit_id and user_id=auth.uid() and status='pending';if not found then raise exception 'Deposit tidak dapat dikonfirmasi';end if;end$$;
create or replace function public.naikin_admin_set_deposit(p_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$declare d public.naikin_deposits%rowtype;begin if not public.naikin_is_admin() then raise exception 'Tidak diizinkan';end if;if p_status not in ('paid','rejected') then raise exception 'Status tidak valid';end if;select * into d from public.naikin_deposits where id=p_id for update;if not found or d.status not in ('pending','user_confirmed') then raise exception 'Deposit sudah diproses';end if;update public.naikin_deposits set status=p_status,verified_at=case when p_status='paid' then now() else null end where id=p_id;if p_status='paid' then insert into public.naikin_ledger(user_id,amount,reference,description) values(d.user_id,d.amount,'deposit:'||p_id,'Deposit terverifikasi') on conflict(reference) do nothing;end if;insert into public.naikin_audit(actor_id,action,target) values(auth.uid(),'deposit:'||p_status,p_id::text);end$$;
create or replace function public.naikin_admin_set_order(p_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$declare o public.naikin_orders%rowtype;begin if not public.naikin_is_admin() then raise exception 'Tidak diizinkan';end if;if p_status not in ('pending','processing','completed','cancelled') then raise exception 'Status tidak valid';end if;select * into o from public.naikin_orders where id=p_id for update;if not found then raise exception 'Pesanan tidak ada';end if;if o.status='cancelled' and p_status<>'cancelled' then raise exception 'Pesanan dibatalkan tidak bisa dibuka ulang';end if;if p_status='cancelled' and o.status<>'cancelled' then insert into public.naikin_ledger(user_id,amount,reference,description) values(o.user_id,o.total,'refund:'||o.id,'Pengembalian pesanan') on conflict(reference) do nothing;end if;update public.naikin_orders set status=p_status where id=p_id;insert into public.naikin_audit(actor_id,action,target) values(auth.uid(),'order:'||p_status,p_id::text);end$$;
revoke all on function public.naikin_place_order(text,integer,text,uuid),public.naikin_create_deposit(numeric,uuid),public.naikin_confirm_deposit(uuid),public.naikin_admin_set_deposit(uuid,text),public.naikin_admin_set_order(uuid,text) from public;
grant execute on function public.naikin_place_order(text,integer,text,uuid),public.naikin_create_deposit(numeric,uuid),public.naikin_confirm_deposit(uuid),public.naikin_admin_set_deposit(uuid,text),public.naikin_admin_set_order(uuid,text) to authenticated;
alter table public.naikin_profiles enable row level security;
alter table public.naikin_products enable row level security;
alter table public.naikin_orders enable row level security;
alter table public.naikin_deposits enable row level security;
alter table public.naikin_ledger enable row level security;
alter table public.naikin_tickets enable row level security;
alter table public.naikin_ticket_messages enable row level security;
alter table public.naikin_site_settings enable row level security;
alter table public.naikin_audit enable row level security;
create policy profiles_read on public.naikin_profiles for select to authenticated using(id=auth.uid() or public.naikin_is_admin());
create policy profiles_update on public.naikin_profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
-- Role protected by trigger; profile users cannot self-promote.
create or replace function public.naikin_protect_profile() returns trigger language plpgsql security definer set search_path='' as $$begin if new.role<>old.role and auth.uid() is not null then raise exception 'Role tidak dapat diubah';end if;return new;end$$;
create trigger naikin_protect_profile before update on public.naikin_profiles for each row execute function public.naikin_protect_profile();
create policy products_read on public.naikin_products for select to anon,authenticated using(active or public.naikin_is_admin());
create policy products_admin_update on public.naikin_products for update to authenticated using(public.naikin_is_admin()) with check(public.naikin_is_admin());
create policy products_admin_insert on public.naikin_products for insert to authenticated with check(public.naikin_is_admin());
create policy orders_read on public.naikin_orders for select to authenticated using(user_id=auth.uid() or public.naikin_is_admin());
create policy deposits_read on public.naikin_deposits for select to authenticated using(user_id=auth.uid() or public.naikin_is_admin());
create policy ledger_read on public.naikin_ledger for select to authenticated using(user_id=auth.uid() or public.naikin_is_admin());
create policy tickets_read on public.naikin_tickets for select to authenticated using(user_id=auth.uid() or public.naikin_is_admin());
create policy tickets_insert on public.naikin_tickets for insert to authenticated with check(user_id=auth.uid());
create policy tickets_admin_update on public.naikin_tickets for update to authenticated using(public.naikin_is_admin()) with check(public.naikin_is_admin());
create policy messages_read on public.naikin_ticket_messages for select to authenticated using(exists(select 1 from public.naikin_tickets t where t.id=ticket_id and (t.user_id=auth.uid() or public.naikin_is_admin())));
create policy messages_insert on public.naikin_ticket_messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.naikin_tickets t where t.id=ticket_id and (t.user_id=auth.uid() or public.naikin_is_admin())));
create policy settings_read on public.naikin_site_settings for select to anon,authenticated using(true);
create policy settings_admin_update on public.naikin_site_settings for update to authenticated using(public.naikin_is_admin()) with check(public.naikin_is_admin());
create policy audit_read on public.naikin_audit for select to authenticated using(public.naikin_is_admin());
